<div class="bertin-app">
  <header class="bertin-header"><div><h2 id="b-title"></h2><p id="b-sub"></p></div><span class="bertin-badge">Bertin Pailley</span></header>
  <div class="bertin-controls"><input id="bertin-search" placeholder="Rechercher nom, ville, CP, type, vague..."><select id="bertin-wave"><option value="">Toutes les vagues</option></select><select id="bertin-type"><option value="">Tous les types</option></select><label><input type="checkbox" id="bertin-photo"> Avec photos</label><span id="bertin-count"></span></div>
  <div class="bertin-layout"><div id="bertin-list"></div><div id="bertin-map"></div></div>
</div>
<div id="bertin-modal" class="bertin-modal" hidden><div class="bertin-modal-content"><button id="bertin-close">×</button><div id="bertin-detail"></div></div></div>
